CREATE TABLE IF NOT EXISTS user_settings ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID REFERENCES schools(id), user_id UUID REFERENCES profiles(id) ON DELETE CASCADE UNIQUE, push_notifications BOOLEAN DEFAULT TRUE, sms_alerts BOOLEAN DEFAULT TRUE, email_reports BOOLEAN DEFAULT FALSE, ai_personalization BOOLEAN DEFAULT TRUE, biometric_login BOOLEAN DEFAULT TRUE, dark_mode BOOLEAN DEFAULT FALSE, language TEXT DEFAULT 'en', updated_at TIMESTAMPTZ DEFAULT NOW() ); 
